        size_t position = text.find(comment);
        if (position != std::string::npos) {
            // Kommentar gefunden, Suchwort überspringen
            continue;
            ++occurrences;
        }
        // Nächstes Zeilenende überspringen
        if (position != std::string::npos && !foundWord) {
            foundWord = true;
        }
    }

    if (foundWord) {
        std::cout << "Das Wort '" << comment << "' erscheint " << occurrences << " Mal in der Datei.\n";
    } else {
        std::cout << "Keine Übereinstimmungen zwischen Suchwort und der Datei gefunden.\n";
    }
}
```

Dieses Beispiel kann ohne Änderungen an den Dateinamen, dem Dateiende und den Standardheaders auch als Teil eines größeren Programms kompiliert werden. Die genauen Bedingungen hängen von der Anforderung ab.

